package com.example.masroofy;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Stage;

class SettingsView {

    private AppManager appManager;

    public SettingsView(AppManager appManager) {
        this.appManager = appManager;
    }

    public VBox getView() {
        VBox root = new VBox();
        root.getStyleClass().add("settings-root");

        Label pageTitle = new Label("Settings");
        pageTitle.getStyleClass().add("page-title");
        VBox.setMargin(pageTitle, new Insets(0, 0, 8, 0));

        // Card 1: Change PIN
        VBox changePinCard = createCard();
        Label changePinTitle = createCardTitle("CHANGE PIN");

        PasswordField oldPinField = createPasswordField("••••");
        PasswordField newPinField = createPasswordField("••••");

        VBox oldPinBox = new VBox(6, createFieldLabel("Old PIN"), oldPinField);
        VBox newPinBox = new VBox(6, createFieldLabel("New PIN"), newPinField);

        Button confirmBtn = new Button("✓");
        confirmBtn.getStyleClass().add("icon-button");
        confirmBtn.setPrefHeight(40);

        // ✅ الحل الجذري: نعمل Label فاضي ونحطه مع الزرار في VBox عشان يبقوا نفس الهيكل
        Label dummyLabel = createFieldLabel(" "); // مسافة فاضية عشان تاخد نفس الارتفاع
        VBox btnBox = new VBox(6, dummyLabel, confirmBtn); // نفس الـ spacing بتاع الخانات

        // Feedback label shown after the user tries to change PIN
        Label pinMsg = new Label();

        confirmBtn.setOnAction(e -> {
            boolean ok = appManager.changePin(oldPinField.getText(), newPinField.getText());
            pinMsg.getStyleClass().setAll(ok ? "msg-success" : "msg-error");
            pinMsg.setText(ok ? "✓ PIN changed successfully." : "✗ Wrong old PIN.");
            oldPinField.clear();
            newPinField.clear();
        });

        // ✅ حطينا الـ btnBox هنا بدل الزرار لوحده
        HBox pinRow = new HBox(10, oldPinBox, newPinBox, btnBox);

        // المحاذاة هتبقى مظبوطة دلوقتي لأن الهياكل كلها بقت متطابقة
        pinRow.setAlignment(Pos.CENTER_LEFT);

        pinRow.getStyleClass().add("form-row");
        HBox.setHgrow(oldPinBox, Priority.ALWAYS);
        HBox.setHgrow(newPinBox, Priority.ALWAYS);

        changePinCard.getChildren().addAll(changePinTitle, pinRow, pinMsg);

        // Card 2: Reset Cycle
        VBox resetCard = createCard();
        Label resetTitle = createCardTitle("RESET CYCLE");

        Label resetDesc = new Label("Clear all expenses and categories for the current cycle. This action cannot be undone.");
        resetDesc.getStyleClass().add("section-help");

        Button resetBtn = new Button("Reset Cycle");
        resetBtn.getStyleClass().add("danger-button");

        Label resetMsg = new Label();

        resetBtn.setOnAction(e -> {
            Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                    "Are you sure? This cannot be undone.",
                    ButtonType.YES, ButtonType.NO);
            confirm.setTitle("Reset Cycle");
            confirm.showAndWait().ifPresent(response -> {
                if (response == ButtonType.YES) {
                    appManager.resetCycle();
                    resetMsg.getStyleClass().setAll("msg-success");
                    resetMsg.setText("✓ Cycle reset.");
                }
            });
        });

        resetCard.getChildren().addAll(resetTitle, resetDesc, resetBtn, resetMsg);

        // Card 3: Manage Categories
        VBox categoryCard = createCard();
        Label categoryTitle = createCardTitle("MANAGE CATEGORIES");

        TextField addCatField = createTextField("Category name");
        Button addCatBtn = new Button("+ Add");
        addCatBtn.getStyleClass().add("primary-button");

        HBox addRow = new HBox(10, addCatField, addCatBtn);
        addRow.getStyleClass().add("form-row");
        HBox.setHgrow(addCatField, Priority.ALWAYS);

        Separator divider = new Separator();
        divider.getStyleClass().add("section-divider");
        VBox.setMargin(divider, new Insets(4, 0, 4, 0));

        TextField deleteCatField = createTextField("Name to delete");
        Button deleteCatBtn = new Button("Delete");
        deleteCatBtn.getStyleClass().add("danger-button");

        HBox deleteRow = new HBox(10, deleteCatField, deleteCatBtn);
        deleteRow.getStyleClass().add("form-row");
        HBox.setHgrow(deleteCatField, Priority.ALWAYS);

        Label currentCatLabel = createFieldLabel("Current categories");
        VBox.setMargin(currentCatLabel, new Insets(12, 0, 4, 0));

        FlowPane tagsPane = new FlowPane();
        tagsPane.getStyleClass().add("tag-row");

        Label catMsg = new Label();

        Runnable refreshTags = () -> {
            tagsPane.getChildren().clear();
            for (String cat : appManager.getCategories()) {
                Label tag = new Label(cat);
                tag.getStyleClass().addAll("tag", resolveTagClass(cat));
                tagsPane.getChildren().add(tag);
            }
        };

        addCatBtn.setOnAction(e -> {
            String name = addCatField.getText().trim();
            if (!name.isEmpty()) {
                appManager.addCategory(name);
                addCatField.clear();
                refreshTags.run();
                catMsg.getStyleClass().setAll("msg-success");
                catMsg.setText("✓ Category added.");
            }
        });

        deleteCatBtn.setOnAction(e -> {
            String name = deleteCatField.getText().trim();
            if (!name.isEmpty()) {
                boolean ok = appManager.deleteCategory(name);
                deleteCatField.clear();
                refreshTags.run();
                catMsg.getStyleClass().setAll(ok ? "msg-success" : "msg-error");
                catMsg.setText(ok ? "✓ Category deleted." : "✗ Category not found.");
            }
        });

        refreshTags.run();

        categoryCard.getChildren().addAll(
                categoryTitle, addRow, divider, deleteRow,
                currentCatLabel, tagsPane, catMsg
        );

        // Card 4: Reset Database
        VBox resetDbCard = createCard();
        resetDbCard.getStyleClass().add("danger-card");

        Label resetDbTitle = createCardTitle("RESET DATABASE");

        Label resetDbDesc = new Label("Wipes everything — current cycle, all expenses, categories, and your PIN.");
        resetDbDesc.getStyleClass().add("section-help");

        Button resetDbBtn = new Button("Reset Database");
        resetDbBtn.getStyleClass().add("danger-button");

        Label resetDbMsg = new Label();

        resetDbBtn.setOnAction(e -> {
            Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                    "This will delete EVERYTHING including your PIN.\nThis cannot be undone.",
                    ButtonType.YES, ButtonType.NO);
            confirm.setTitle("Reset Database");
            confirm.showAndWait().ifPresent(response -> {
                if (response == ButtonType.YES) {
                    resetDbMsg.getStyleClass().setAll("msg-success");
                    resetDbMsg.setText("✓ Database reset. Please restart the app.");
                    resetDbBtn.setDisable(true);
                }
            });
        });

        resetDbCard.getChildren().addAll(resetDbTitle, resetDbDesc, resetDbBtn, resetDbMsg);

        VBox content = new VBox(16,
                pageTitle,
                changePinCard,
                resetCard,
                categoryCard,
                resetDbCard
        );
        content.setPadding(new Insets(28, 24, 28, 24));
        content.setAlignment(Pos.TOP_CENTER);
        content.getStyleClass().add("settings-container");

        HBox centerWrapper = new HBox(content);
        centerWrapper.setAlignment(Pos.TOP_CENTER);

        ScrollPane scroll = new ScrollPane(centerWrapper);
        scroll.setFitToWidth(true);
        scroll.getStyleClass().add("settings-scroll");

        root.getChildren().add(scroll);
        VBox.setVgrow(scroll, Priority.ALWAYS);

        return root;
    }

    private VBox createCard() {
        VBox card = new VBox(12);
        card.getStyleClass().add("settings-card");
        return card;
    }

    private Label createCardTitle(String text) {
        Label label = new Label(text);
        label.getStyleClass().add("card-title");
        return label;
    }

    private Label createFieldLabel(String text) {
        Label label = new Label(text);
        label.getStyleClass().add("tags-label");
        return label;
    }

    private PasswordField createPasswordField(String placeholder) {
        PasswordField field = new PasswordField();
        field.setPromptText(placeholder);
        field.getStyleClass().add("text-input");
        return field;
    }

    private TextField createTextField(String placeholder) {
        TextField field = new TextField();
        field.setPromptText(placeholder);
        field.getStyleClass().add("text-input");
        return field;
    }

    private String resolveTagClass(String name) {
        return switch (name.toLowerCase()) {
            case "food"          -> "tag-food";
            case "transport"     -> "tag-transport";
            case "health"        -> "tag-health";
            case "entertainment" -> "tag-ent";
            case "utilities"     -> "tag-util";
            default              -> "tag-transport";
        };
    }
}

package com.example.masroofy;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Stage;

class SettingsView {

    private AppManager appManager;
    private Runnable onLogout; // Added onLogout

    public SettingsView(AppManager appManager, Runnable onLogout) {
        this.appManager = appManager;
        this.onLogout = onLogout;
    }

    public SettingsView(AppManager appManager) {
        this.appManager = appManager;
    }

    public VBox getView() {
        VBox root = new VBox();
        root.getStyleClass().add("settings-root");

        Label pageTitle = new Label("Settings");
        pageTitle.getStyleClass().add("page-title");
        VBox.setMargin(pageTitle, new Insets(0, 0, 8, 0));

        // Card 1: Change PIN
        VBox changePinCard = createCard();
        Label changePinTitle = createCardTitle("CHANGE PIN");

        PasswordField oldPinField = createPasswordField("••••");
        PasswordField newPinField = createPasswordField("••••");

        VBox oldPinBox = new VBox(6, createFieldLabel("Old PIN"), oldPinField);
        VBox newPinBox = new VBox(6, createFieldLabel("New PIN"), newPinField);

        Button confirmBtn = new Button("✓");
        confirmBtn.getStyleClass().add("icon-button");
        confirmBtn.setPrefHeight(40);

        // ✅ الحل الجذري: نعمل Label فاضي ونحطه مع الزرار في VBox عشان يبقوا نفس الهيكل
        Label dummyLabel = createFieldLabel(" "); // مسافة فاضية عشان تاخد نفس الارتفاع
        VBox btnBox = new VBox(6, dummyLabel, confirmBtn); // نفس الـ spacing بتاع الخانات

        // Feedback label shown after the user tries to change PIN
        Label pinMsg = new Label();

        confirmBtn.setOnAction(e -> {
            boolean ok = appManager.changePin(oldPinField.getText(), newPinField.getText());
            pinMsg.getStyleClass().setAll(ok ? "msg-success" : "msg-error");
            pinMsg.setText(ok ? "✓ PIN changed successfully." : "✗ Wrong old PIN.");
            oldPinField.clear();
            newPinField.clear();
        });

        // ✅ حطينا الـ btnBox هنا بدل الزرار لوحده
        HBox pinRow = new HBox(10, oldPinBox, newPinBox, btnBox);

        // المحاذاة هتبقى مظبوطة دلوقتي لأن الهياكل كلها بقت متطابقة
        pinRow.setAlignment(Pos.CENTER_LEFT);

        pinRow.getStyleClass().add("form-row");
        HBox.setHgrow(oldPinBox, Priority.ALWAYS);
        HBox.setHgrow(newPinBox, Priority.ALWAYS);

        changePinCard.getChildren().addAll(changePinTitle, pinRow, pinMsg);

        // Card 2: Reset Cycle
        VBox resetCard = createCard();
        Label resetTitle = createCardTitle("RESET CYCLE");

        Label resetDesc = new Label("Clear all expenses and categories for the current cycle. This action cannot be undone.");
        resetDesc.getStyleClass().add("section-help");

        Button resetBtn = new Button("Reset Cycle");
        resetBtn.getStyleClass().add("danger-button");

        Label resetMsg = new Label();

        resetBtn.setOnAction(e -> {
            Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                    "Are you sure? This cannot be undone.",
                    ButtonType.YES, ButtonType.NO);
            confirm.setTitle("Reset Cycle");
            confirm.showAndWait().ifPresent(response -> {
                if (response == ButtonType.YES) {
                    appManager.resetCycle();
                    resetMsg.getStyleClass().setAll("msg-success");
                    resetMsg.setText("✓ Cycle reset.");
                }
            });
        });

        resetCard.getChildren().addAll(resetTitle, resetDesc, resetBtn, resetMsg);

        // Card 3: Manage Categories
        VBox categoryCard = createCard();
        Label categoryTitle = createCardTitle("MANAGE CATEGORIES");

        TextField addCatField = createTextField("Category name");
        Button addCatBtn = new Button("+ Add");
        addCatBtn.getStyleClass().add("primary-button");

        HBox addRow = new HBox(10, addCatField, addCatBtn);
        addRow.getStyleClass().add("form-row");
        HBox.setHgrow(addCatField, Priority.ALWAYS);

        Separator divider = new Separator();
        divider.getStyleClass().add("section-divider");
        VBox.setMargin(divider, new Insets(4, 0, 4, 0));

        TextField deleteCatField = createTextField("Name to delete");
        Button deleteCatBtn = new Button("Delete");
        deleteCatBtn.getStyleClass().add("danger-button");

        HBox deleteRow = new HBox(10, deleteCatField, deleteCatBtn);
        deleteRow.getStyleClass().add("form-row");
        HBox.setHgrow(deleteCatField, Priority.ALWAYS);

        Label currentCatLabel = createFieldLabel("Current categories");
        VBox.setMargin(currentCatLabel, new Insets(12, 0, 4, 0));

        FlowPane tagsPane = new FlowPane();
        tagsPane.getStyleClass().add("tag-row");

        Label catMsg = new Label();

        Runnable refreshTags = () -> {
            tagsPane.getChildren().clear();
            for (String cat : appManager.getCategories()) {
                Label tag = new Label(cat);
                tag.getStyleClass().addAll("tag", resolveTagClass(cat));
                tagsPane.getChildren().add(tag);
            }
        };

        addCatBtn.setOnAction(e -> {
            String name = addCatField.getText().trim();
            if (!name.isEmpty()) {
                appManager.addCategory(name);
                addCatField.clear();
                refreshTags.run();
                catMsg.getStyleClass().setAll("msg-success");
                catMsg.setText("✓ Category added.");
            }
        });

        deleteCatBtn.setOnAction(e -> {
            String name = deleteCatField.getText().trim();
            if (!name.isEmpty()) {
                boolean ok = appManager.deleteCategory(name);
                deleteCatField.clear();
                refreshTags.run();
                catMsg.getStyleClass().setAll(ok ? "msg-success" : "msg-error");
                catMsg.setText(ok ? "✓ Category deleted." : "✗ Category not found.");
            }
        });

        refreshTags.run();

        categoryCard.getChildren().addAll(
                categoryTitle, addRow, divider, deleteRow,
                currentCatLabel, tagsPane, catMsg
        );

        // Card 4: Delete Account
        VBox resetDbCard = createCard();
        resetDbCard.getStyleClass().add("danger-card");

        Label resetDbTitle = createCardTitle("DELETE ACCOUNT");

        Label resetDbDesc = new Label("Wipes your entire account — cycles, expenses, categories, and your user data.");
        resetDbDesc.getStyleClass().add("section-help");

        Button resetDbBtn = new Button("Delete Account");
        resetDbBtn.getStyleClass().add("danger-button");

        Label resetDbMsg = new Label();

        resetDbBtn.setOnAction(e -> {
            Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                    "This will delete EVERYTHING including your account.\nThis cannot be undone.",
                    ButtonType.YES, ButtonType.NO);
            confirm.setTitle("Delete Account");
            confirm.showAndWait().ifPresent(response -> {
                if (response == ButtonType.YES) {
                    appManager.deleteCurrentAccount();
                    resetDbMsg.getStyleClass().setAll("msg-success");
                    resetDbMsg.setText("✓ Account deleted.");
                    resetDbBtn.setDisable(true);
                    if (onLogout != null) {
                        onLogout.run();
                    }
                }
            });
        });

        resetDbCard.getChildren().addAll(resetDbTitle, resetDbDesc, resetDbBtn, resetDbMsg);

        VBox content = new VBox(16,
                pageTitle,
                changePinCard,
                resetCard,
                categoryCard,
                resetDbCard
        );
        content.setPadding(new Insets(28, 24, 28, 24));
        content.setAlignment(Pos.TOP_CENTER);
        content.getStyleClass().add("settings-container");

        HBox centerWrapper = new HBox(content);
        centerWrapper.setAlignment(Pos.TOP_CENTER);

        ScrollPane scroll = new ScrollPane(centerWrapper);
        scroll.setFitToWidth(true);
        scroll.getStyleClass().add("settings-scroll");

        root.getChildren().add(scroll);
        VBox.setVgrow(scroll, Priority.ALWAYS);

        return root;
    }

    private VBox createCard() {
        VBox card = new VBox(12);
        card.getStyleClass().add("settings-card");
        return card;
    }

    private Label createCardTitle(String text) {
        Label label = new Label(text);
        label.getStyleClass().add("card-title");
        return label;
    }

    private Label createFieldLabel(String text) {
        Label label = new Label(text);
        label.getStyleClass().add("tags-label");
        return label;
    }

    private PasswordField createPasswordField(String placeholder) {
        PasswordField field = new PasswordField();
        field.setPromptText(placeholder);
        field.getStyleClass().add("text-input");
        return field;
    }

    private TextField createTextField(String placeholder) {
        TextField field = new TextField();
        field.setPromptText(placeholder);
        field.getStyleClass().add("text-input");
        return field;
    }

    private String resolveTagClass(String name) {
        return switch (name.toLowerCase()) {
            case "food"          -> "tag-food";
            case "transport"     -> "tag-transport";
            case "health"        -> "tag-health";
            case "entertainment" -> "tag-ent";
            case "utilities"     -> "tag-util";
            default              -> "tag-transport";
        };
    }
}

package com.example.masroofy;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Node;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.HBox;
import javafx.scene.layout.Region;
import javafx.scene.layout.VBox;

class StatsView {

    private final AppManager appManager;
    private final Runnable onViewHistory;

    StatsView(AppManager appManager, Runnable onViewHistory) {
        this.appManager = appManager;
        this.onViewHistory = onViewHistory;
    }

    VBox getView() {
        VBox root = new VBox(16);
        root.getStyleClass().add("stats-root");
        root.setPadding(new Insets(24, 20, 24, 20));

        Label title = new Label("Weekly Stats");
        title.getStyleClass().add("stats-title");

        VBox weeklyCard = new VBox(10);
        weeklyCard.getStyleClass().add("stats-card");
        weeklyCard.setAlignment(Pos.CENTER);

        Label totalLabel = new Label("Total Spent This Week");
        totalLabel.getStyleClass().add("stats-subtitle");

        double weeklyTotal = appManager.getWeeklyTotalSpent();
        Label amountLabel = new Label(formatAmount(weeklyTotal));
        amountLabel.getStyleClass().add("stats-amount");

        Label currencyLabel = new Label("EGP");
        currencyLabel.getStyleClass().add("stats-currency");

        Button historyButton = new Button("View History");
        historyButton.getStyleClass().add("stats-ghost-button");
        historyButton.setMaxWidth(Double.MAX_VALUE);
        historyButton.setOnAction(event -> {
            if (onViewHistory != null) {
                onViewHistory.run();
            }
        });

        weeklyCard.getChildren().addAll(totalLabel, amountLabel, currencyLabel, historyButton);

        VBox breakdownCard = new VBox(12);
        breakdownCard.getStyleClass().add("stats-card");

        Label breakdownTitle = new Label("Spending by Category");
        breakdownTitle.getStyleClass().add("stats-section-title");

        VBox rows = new VBox(10);
        rows.getChildren().addAll(buildCategoryRows());

        breakdownCard.getChildren().addAll(breakdownTitle, rows);

        root.getChildren().addAll(title, weeklyCard, breakdownCard);
        return root;
    }

    private List<Node> buildCategoryRows() {
        Map<String, Double> totals = appManager.getCategoryTotals();
        List<Node> rows = new ArrayList<>();

        double total = totals.values().stream().mapToDouble(Double::doubleValue).sum();
        if (total <= 0) {
            Label empty = new Label("No data yet");
            empty.getStyleClass().add("stats-empty");
            rows.add(empty);
            return rows;
        }

        totals.entrySet().stream()
                .sorted(Comparator.comparingDouble((Map.Entry<String, Double> e) -> e.getValue()).reversed())
                .forEach(entry -> rows.add(buildCategoryRow(entry.getKey(), entry.getValue(), total)));

        return rows;
    }

    private HBox buildCategoryRow(String name, double amount, double total) {
        HBox row = new HBox(10);
        row.setAlignment(Pos.CENTER_LEFT);

        Region dot = new Region();
        dot.getStyleClass().add("stats-dot");

        Label nameLabel = new Label(name);
        nameLabel.getStyleClass().add("stats-row-label");

        double percent = total == 0 ? 0 : (amount / total) * 100.0;
        Label percentLabel = new Label(String.format(Locale.US, "%.0f%%", percent));
        percentLabel.getStyleClass().add("stats-row-value");

        Region spacer = new Region();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);

        row.getChildren().addAll(dot, nameLabel, spacer, percentLabel);
        return row;
    }

    private String formatAmount(double value) {
        if (value == (long) value) {
            return String.format(Locale.US, "%d", (long) value);
        }
        return String.format(Locale.US, "%.2f", value);
    }
}

package com.example.masroofy;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Node;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.HBox;
import javafx.scene.layout.Region;
import javafx.scene.layout.VBox;
import javafx.scene.control.ScrollPane;

class StatsView {

    private final AppManager appManager;
    private final Runnable onViewHistory;

    StatsView(AppManager appManager, Runnable onViewHistory) {
        this.appManager = appManager;
        this.onViewHistory = onViewHistory;
    }

    VBox getView() {
        VBox root = new VBox();
        root.getStyleClass().add("settings-root");

        ScrollPane scroll = new ScrollPane();
        scroll.setFitToWidth(true);
        scroll.getStyleClass().add("settings-scroll");
        scroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);

        VBox container = new VBox(20);
        container.setPadding(new Insets(28, 24, 28, 24));

        Label title = new Label("Weekly Stats");
        title.getStyleClass().add("page-title");

        VBox weeklyCard = new VBox(10);
        weeklyCard.getStyleClass().add("settings-card");
        weeklyCard.setAlignment(Pos.CENTER);

        Label totalLabel = new Label("Total Spent This Week");
        totalLabel.getStyleClass().add("card-title");

        double weeklyTotal = appManager.getWeeklyTotalSpent();
        Label amountLabel = new Label(formatAmount(weeklyTotal));
        amountLabel.setStyle("-fx-text-fill: #EDE9FF; -fx-font-size: 34px; -fx-font-weight: bold;");

        Label currencyLabel = new Label("EGP");
        currencyLabel.getStyleClass().add("section-help");

        Button historyButton = new Button("View History");
        historyButton.getStyleClass().add("ghost-button");
        historyButton.setMaxWidth(Double.MAX_VALUE);
        historyButton.setOnAction(event -> {
            if (onViewHistory != null) {
                onViewHistory.run();
            }
        });

        weeklyCard.getChildren().addAll(totalLabel, amountLabel, currencyLabel, historyButton);

        VBox breakdownCard = new VBox(12);
        breakdownCard.getStyleClass().add("settings-card");

        Label breakdownTitle = new Label("SPENDING BY CATEGORY");
        breakdownTitle.getStyleClass().add("card-title");

        VBox rows = new VBox(10);
        rows.getChildren().addAll(buildCategoryRows());

        breakdownCard.getChildren().addAll(breakdownTitle, rows);

        container.getChildren().addAll(title, weeklyCard, breakdownCard);
        scroll.setContent(container);
        root.getChildren().add(scroll);
        
        return root;
    }

    private List<Node> buildCategoryRows() {
        Map<String, Double> totals = appManager.getCategoryTotals();
        List<Node> rows = new ArrayList<>();

        double total = totals.values().stream().mapToDouble(Double::doubleValue).sum();
        if (total <= 0) {
            Label empty = new Label("No data yet");
            empty.getStyleClass().add("section-help");
            rows.add(empty);
            return rows;
        }

        int[] colorIndex = {0};
        String[] colors = {"#7C3AED", "#4ADE80", "#38BDF8", "#FBBF24", "#F87171", "#C084FC", "#FB923C", "#818CF8"};

        totals.entrySet().stream()
                .sorted(Comparator.comparingDouble((Map.Entry<String, Double> e) -> e.getValue()).reversed())
                .forEach(entry -> {
                    String color = colors[colorIndex[0] % colors.length];
                    colorIndex[0]++;
                    rows.add(buildCategoryRow(entry.getKey(), entry.getValue(), total, color));
                });

        return rows;
    }

    private HBox buildCategoryRow(String name, double amount, double total, String color) {
        HBox row = new HBox(10);
        row.setAlignment(Pos.CENTER_LEFT);

        Region dot = new Region();
        dot.setMinSize(10, 10);
        dot.setMaxSize(10, 10);
        dot.setStyle("-fx-background-color: " + color + "; -fx-background-radius: 50%;");

        Label nameLabel = new Label(name);
        nameLabel.getStyleClass().add("tx-name");

        double percent = total == 0 ? 0 : (amount / total) * 100.0;
        Label percentLabel = new Label(String.format(Locale.US, "%.0f%%", percent));
        percentLabel.getStyleClass().add("tx-amount");

        Region spacer = new Region();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);

        row.getChildren().addAll(dot, nameLabel, spacer, percentLabel);
        return row;
    }

    private String formatAmount(double value) {
        if (value == (long) value) {
            return String.format(Locale.US, "%d", (long) value);
        }
        return String.format(Locale.US, "%.2f", value);
    }
}
